import json,html
from pathlib import Path
root=Path(__file__).resolve().parent
data=json.loads((root/'research.json').read_text(encoding='utf-8'))
esc=html.escape
cards=[]
for i,g in enumerate(data['games'],1):
    links=' · '.join(f'<a href="{esc(s["url"])}" target="_blank" rel="noopener">{esc(s["label"])}</a>' for s in g['sources'])
    extra=f'<a class="extra" href="{g["extraImage"]}" target="_blank">가계도 화면 크게 보기 ↗</a>' if 'extraImage' in g else ''
    cards.append(f'''<article id="{g['id']}" class="game-card"><div class="card-top"><span class="number">{i:02}</span><div><p class="role">{esc(g['role'])}</p><h2>{esc(g['title'])}</h2></div></div><a class="shot" href="{g['image']}" target="_blank"><img src="{g['image']}" alt="{esc(g['imageNote'])}"></a><p class="caption">{esc(g['imageNote'])} · 누르면 원본 크기 {extra}</p><div class="copy"><h3>실제로 하는 조작</h3><p>{esc(g['actions'])}</p><h3>판단해야 하는 것</h3><p>{esc(g['judgment'])}</p><div class="analysis"><h3>공문에 참고할 원리 · 조사자의 해석</h3><p>{esc(g['interpretation'])}</p><p>{esc(g['transfer'])}</p></div><p class="risk"><b>그대로 가져올 때의 문제</b> {esc(g['risk'])}</p><div class="sources">{links}</div></div></article>''')
nav=''.join(f'<a href="#{g["id"]}">{esc(g["title"])}</a>' for g in data['games'])
style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#1e291c;color:#f4eedb;font:15px/1.65 'Malgun Gothic',system-ui,sans-serif}.wrap{max-width:1160px;margin:auto;padding:35px 24px 70px}header{padding-bottom:22px;border-bottom:1px solid #4a5a3e}.kick{font-size:12px;color:#d9b662;letter-spacing:1px}h1{font-size:32px;margin:8px 0 13px;line-height:1.3}p{margin:6px 0}header>p{max-width:850px;color:#cbd1ba}.lead{font-size:19px;color:#f1e9cb!important;font-weight:700}.excluded{font-size:12px;color:#aebc9c!important;margin-top:12px}nav{display:flex;gap:7px;flex-wrap:wrap;margin:20px 0}a{color:#ddbf70;text-decoration:none}nav a{border:1px solid #596a47;border-radius:7px;padding:6px 10px;font-size:12px;background:#30402a}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:start}.game-card{background:#f4eedb;color:#2c3628;border:1px solid #b6ac84;border-radius:12px;overflow:hidden;scroll-margin-top:20px}.card-top{display:flex;gap:12px;align-items:center;padding:16px 18px;background:#e7dec1}.number{font-size:25px;font-weight:900;color:#8b723b;border-right:1px solid #baa77a;padding-right:12px}.role{font-size:11px;color:#697059}.card-top h2{font-size:20px;margin:0;line-height:1.3}.shot{display:flex;align-items:center;justify-content:center;background:#142011;height:280px;padding:12px}.shot img{display:block;max-width:100%;max-height:100%;object-fit:contain}.game-card:first-child .shot img,.game-card:last-child .shot img{image-rendering:pixelated}.caption{font-size:10px;color:#74765e;padding:8px 16px 0}.caption a{color:#516c41;text-decoration:underline}.copy{padding:12px 18px 18px}.copy h3{font-size:13px;margin:12px 0 3px;color:#4e6840}.copy p{font-size:13px;line-height:1.65}.analysis{padding:5px 11px 9px;margin:12px -2px;background:#e2e8ce;border-left:3px solid #7c985d;border-radius:3px}.analysis h3{margin-top:4px}.copy .risk{font-size:12px;color:#7c5941;padding-top:5px}.risk b{display:block}.sources{margin-top:13px;padding-top:10px;border-top:1px solid #cfc5a2;font-size:11px}.sources a{color:#416536;text-decoration:underline}.summary{border:1px solid #5b704a;border-radius:9px;padding:17px 20px;margin-top:24px;background:#30402a}.summary h2{font-size:20px;margin:0 0 10px}.summary p{font-size:14px;color:#d8ddc6}.summary .scope{font-size:12px;color:#b9c3a7;margin-top:12px}footer{font-size:11px;color:#b7c4a6;margin-top:25px}a:focus-visible{outline:3px solid #cda94c;outline-offset:3px}@media(max-width:760px){.wrap{padding:23px 14px 45px}.grid{grid-template-columns:1fr}h1{font-size:26px}.lead{font-size:16px}.shot{height:auto;min-height:210px}.shot img{max-height:320px}.copy{padding:10px 15px 16px}.card-top{padding:13px 15px}.card-top h2{font-size:19px}nav{gap:5px}nav a{font-size:11px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
text=f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>공문 퍼즐 · 새 참고 게임 6개 조사</title><style>{style}</style></head><body><main class="wrap"><header><div class="kick">생활보장과 · 공문 퍼즐 재설계 조사 · {data['date']}</div><h1>문서를 다루는 행동은<br>어떻게 게임이 되는가</h1><p class="lead">양식 입력, 도구 조사, 특징 대조, 정보 선별, 관계 추론, 내용 편집을 비교합니다.</p><p>공문 하나를 처음부터 설계하기 위해, 손으로 하는 조작과 머리로 해야 하는 판단을 나누어 살펴봤습니다. 아래의 공문 적용 원리는 조사자의 해석입니다.</p><p class="excluded">앞서 조사한 게임 제외: {esc(' · '.join(data['excluded']))}</p></header><nav aria-label="게임별 조사">{nav}</nav><section class="grid">{''.join(cards)}</section><section class="summary"><h2>공문 하나에 우선 참고할 세 가지</h2><p>{esc(data['conclusion'])}</p><p>출처에서 값을 찾았다는 이유만으로 옮기게 하기보다, 어떤 조건 때문에 그 값이 맞는지 판단하게 하는 구조가 필요합니다. 완성한 문서는 그 판단이 담긴 결과물이어야 합니다.</p><p class="scope">{esc(data['scope'])}</p><p class="scope">조사 범위: {esc(data['evidence'])}</p></section><footer>이미지는 개발자·배급사가 공개한 화면이며 연구·비교용으로 출처를 표시했습니다. 실제 게임 이미지와 새로운 시안을 혼동하지 않도록 구분했습니다. 게임 코드와 에셋을 신규 퍼즐에 재사용하지 않습니다.</footer></main></body></html>'''
(root/'공문퍼즐_참고게임조사.html').write_text(text,encoding='utf-8')
print('Built reference-game research report with six game images.')
